 await page.locator('[data-action="head"]').click();
 await page.locator('[data-action="board"]').click();
 await page.evaluate(()=>{current.selected=current.suspects.find(s=>s!==current.killer).name;renderBoard()});
 await page.locator('[data-action="accuse"]').click();
 if(!(await read()).toUpperCase().includes('COLD CASE')) throw Error('incorrect accusation did not lose');
