  text-transform: uppercase;
  color: var(--muted-2);
}

.top-meta {
  display: none;
  align-items: center;
  gap: 10px;
  font: 9px/1 var(--font-mono);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
}

.live-dot {
  width: 6px;
  height: 6px;
  flex: none;
  border-radius: 50%;
  background: #b55d4d;
  box-shadow: 0 0 10px rgba(196, 95, 78, 0.9);
}

.meta-rule {
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: var(--muted-2);
