.ghost-btn {
  min-height: 40px;
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 0 11px;
  border: 1px solid rgba(236, 227, 207, 0.2);
  background: transparent;
  color: #c3beae;
  font: 500 9px/1 var(--font-mono);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  cursor: pointer;
  transition: color 0.2s, border-color 0.2s, background 0.2s;
}

.ghost-btn:hover {
  border-color: var(--gold);
  color: var(--paper);
  background: rgba(201, 168, 106, 0.06);
}

.ghost-btn-icon {
  color: var(--gold);
  font-size: 15px;
  line-height: 1;
}

.game-frame {
  flex: 1;
  width: 100%;
  padding: 24px 0 34px;
}

.footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 0 calc(16px + env(safe-area-inset-bottom));
  border-top: 1px solid rgba(236, 227, 207, 0.09);
  color: #6e6f64;
  font: 8px/1.4 var(--font-mono);
  letter-spacing: 0.11em;
  text-transform: uppercase;
}

.footer span:last-child {
  display: none;
}

/* ------------------------------------------------------------
   Type, buttons, small parts
   ------------------------------------------------------------ */

.screen {
  width: 100%;
  animation: screen-in 0.55s var(--ease) both;
}

@keyframes screen-in {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: var(--gold);
  font: 500 9px/1.4 var(--font-mono);
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.eyebrow::before {
  content: '';
  width: 22px;
  height: 1px;
  flex: none;
  background: currentColor;
  opacity: 0.8;
}

.display {
  margin: 14px 0 16px;
  color: #f0e9d9;
  font: 500 clamp(2.7rem, 12.2vw, 5.4rem) / 0.96 var(--font-display);
  letter-spacing: -0.035em;
}

.display em {
  color: var(--gold-bright);
  font-weight: 500;
}

.lede {
  max-width: 46ch;
  color: #a9a798;
  font-size: 14px;
  line-height: 1.6;
}

.icon {
  width: 18px;
  height: 18px;
  flex: none;
  display: inline-block;
  vertical-align: middle;
}

.btn {
  min-height: 50px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 0 20px;
  border: 1px solid transparent;
  border-radius: 1px;
  font: 500 10px/1 var(--font-mono);
  letter-spacing: 0.13em;
  text-transform: uppercase;
  text-decoration: none;
  cursor: pointer;
  transition: background 0.2s, color 0.2s, border-color 0.2s, transform 0.2s;
}

.btn .icon {
  width: 16px;
  height: 16px;
}

.btn-primary {
  background: var(--gold);
  color: #171811;
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.32);
}

.btn-primary:hover {
  background: var(--gold-bright);
  transform: translateY(-1px);
}

.btn-ghost {
  border-color: var(--line-strong);
  background: rgba(255, 255, 255, 0.015);
  color: var(--paper);
}

.btn-ghost:hover {
  border-color: var(--gold);
  color: var(--gold-bright);
  background: rgba(201, 168, 106, 0.05);
}

.btn-danger {
  background: var(--oxblood);
  color: #fff2e4;
}

.btn-danger:hover {
  background: #ad5042;
}

.btn:disabled {
  opacity: 0.38;
  cursor: not-allowed;
  transform: none;
}

.btn-block {
  width: 100%;
}

.page-head {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 18px;
}

.page-head h1 {
  margin-top: 8px;
  color: #efe8d8;
  font: 500 clamp(2rem, 8vw, 3.6rem) / 1 var(--font-display);
  letter-spacing: -0.03em;
}

.location {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 7px;
  color: var(--muted);
  font: 9px/1.5 var(--font-mono);
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.location .icon {
  width: 13px;
  height: 13px;
  color: var(--gold);
}

.location strong {
  color: #d9d3c2;
  font-weight: 400;
}

.location small {
  flex-basis: 100%;
  color: #8b6f4e;
  font-size: 8px;
  letter-spacing: 0.16em;
}

