  bottom: 14%;
  width: 18%;
  height: 24%;
  z-index: 3;
}

.scene-coat::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(145deg, #37352d, #161712 68%);
  clip-path: polygon(27% 0, 73% 0, 100% 28%, 84% 100%, 16% 100%, 0 28%);
  box-shadow: 0 10px 18px rgba(0, 0, 0, 0.55);
}

.scene-coat i {
  position: absolute;
  left: 50%;
  top: 12%;
  width: 2px;
  height: 62%;
  background: #4c473b;
  transform: translateX(-50%);
}

.scene-body {
  position: absolute;
  left: 44%;
  top: 46%;
  width: 20%;
  height: 17%;
  z-index: 4;
  transform: rotate(-7deg);
}

.s-blood {
  position: absolute;
  left: 46%;
  top: 12%;
  width: 72%;
  height: 62%;
  border-radius: 50%;
  background: radial-gradient(ellipse, rgba(116, 44, 36, 0.85), rgba(72, 27, 23, 0.2) 70%);
  filter: blur(4px);
}

.s-chalk {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  opacity: 0.72;
}

.lamp-glow {
  position: absolute;
  left: 34%;
  top: 26%;
  width: 44%;
  height: 52%;
  z-index: 2;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(235, 189, 108, 0.15), transparent 68%);
  pointer-events: none;
}

.debris {
  position: absolute;
  z-index: 4;
  width: 16px;
  height: 10px;
  background: rgba(216, 206, 184, 0.65);
  transform: rotate(14deg);
  box-shadow: 0 2px 3px rgba(0, 0, 0, 0.35);
}

.debris.d1 {
  left: 39%;
  top: 28%;
}

.debris.d2 {
  left: 66%;
  top: 63%;
  width: 11px;
  height: 8px;
  transform: rotate(-22deg);
}

.debris.d3 {
  left: 33%;
  top: 72%;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: #b59151;
  transform: none;
  box-shadow: 0 0 6px rgba(201, 168, 106, 0.6);
}

.hotspot {
  position: absolute;
  z-index: 10;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 0;
  border: 0;
  background: none;
  cursor: pointer;
}

.hotspot-dot {
  position: relative;
  width: 46px;
  height: 46px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(201, 168, 106, 0.7);
  border-radius: 50%;
  background: rgba(10, 12, 9, 0.86);
  color: var(--gold-bright);
  box-shadow: 0 0 0 5px rgba(201, 168, 106, 0.08), 0 8px 20px rgba(0, 0, 0, 0.5);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  transition: background 0.2s, color 0.2s, transform 0.2s;
}

.hotspot-dot .icon {
  width: 19px;
  height: 19px;
}

.hotspot-dot::after {
  content: '';
  position: absolute;
  inset: -5px;
  border: 1px solid rgba(201, 168, 106, 0.4);
  border-radius: 50%;
  animation: hotspot-pulse 2.6s ease-out infinite;
}

@keyframes hotspot-pulse {
  0% { transform: scale(0.92); opacity: 0.8; }
  70%, 100% { transform: scale(1.35); opacity: 0; }
}

.hotspot:hover .hotspot-dot {
  background: var(--gold);
  color: #171811;
  transform: scale(1.07);
}

.hotspot-tag {
  display: none;
  padding: 4px 6px;
  border: 1px solid rgba(255, 255, 255, 0.09);
  background: rgba(9, 10, 8, 0.84);
  color: #e8dcc0;
  font: 8px/1 var(--font-mono);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  white-space: nowrap;
}

.hotspot.is-found .hotspot-dot {
  border-color: rgba(143, 163, 133, 0.85);
  background: rgba(48, 64, 50, 0.9);
  color: #dce8d5;
}

.hotspot.is-found .hotspot-dot::after {
  display: none;
}

.hotspot-check {
  position: absolute;
  top: -3px;
  right: -3px;
  width: 17px;
  height: 17px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: var(--green);
  color: #11140f;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.5);
}

.hotspot-check .icon {
  width: 10px;
  height: 10px;
}

.spot-desk { left: 14%; top: 23%; }
.spot-window { right: 14%; top: 15%; }
.spot-coat { right: 17%; bottom: 21%; }
.spot-body { left: 46%; top: 57%; }

.scene-caption {
  position: absolute;
  left: 14px;
  bottom: 13px;
  z-index: 10;
  display: flex;
  align-items: center;
  gap: 6px;
  color: rgba(232, 220, 192, 0.7);
  font: 8px/1 var(--font-mono);
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.scene-caption .icon {
  width: 12px;
  height: 12px;
  color: var(--gold);
}

.scene-panel {
  display: flex;
  flex-direction: column;
  padding: 20px 18px;
  border: 1px solid var(--line-strong);
  background: linear-gradient(180deg, rgba(28, 30, 24, 0.97), rgba(18, 20, 16, 0.98));
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.35);
}

.panel-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.kicker {
  color: var(--muted-2);
  font: 8.5px/1 var(--font-mono);
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.mono-badge {
  padding: 4px 7px;
  border: 1px solid rgba(201, 168, 106, 0.32);
  color: var(--gold);
  font: 9px/1 var(--font-mono);
  letter-spacing: 0.08em;
}

.scene-panel h2 {
  margin: 9px 0 7px;
  color: #e9e1cf;
  font: 500 clamp(1.45rem, 5vw, 1.9rem) / 1.05 var(--font-display);
  letter-spacing: -0.02em;
}

.panel-copy {
  margin-bottom: 14px;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.5;
}

.victim-strip {
  display: flex;
  align-items: center;
  gap: 11px;
  margin-bottom: 13px;
  padding: 11px 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.victim-avatar {
  position: relative;
  width: 42px;
  height: 42px;
  flex: none;
  overflow: hidden;
  border: 1px solid #64573e;
  background: radial-gradient(circle at 50% 30%, #b78d66 0 18%, #42382e 19% 46%, #151612 47%);
}

.victim-avatar::after {
  content: '';
  position: absolute;
  left: 14%;
  right: 14%;
  bottom: -12%;
  height: 42%;
  background: linear-gradient(#4c4437, #151612);
  clip-path: polygon(18% 0, 82% 0, 100% 100%, 0 100%);
}

.victim-strip small {
  display: block;
  margin-bottom: 2px;
  color: var(--muted-2);
  font: 8px/1.2 var(--font-mono);
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.victim-strip strong {
  display: block;
  color: #e4dcc9;
  font: 500 16px/1.15 var(--font-display);
}

.victim-strip em {
  display: block;
  margin-top: 2px;
  color: var(--muted-2);
  font: 8px/1.2 var(--font-mono);
  font-style: normal;
  letter-spacing: 0.05em;
}

.poi-list {
  display: grid;
  gap: 6px;
  margin-bottom: 12px;
}

.poi {
  display: flex;
  align-items: center;
  gap: 9px;
  width: 100%;
  min-height: 52px;
  padding: 7px 9px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.018);
  color: var(--paper);
  text-align: left;
  cursor: pointer;
  transition: border-color 0.2s, background 0.2s;
}

.poi:hover {
  border-color: rgba(201, 168, 106, 0.5);
  background: rgba(201, 168, 106, 0.045);
}

.poi.is-found {
  border-color: rgba(143, 163, 133, 0.3);
  background: rgba(143, 163, 133, 0.045);
}

.poi-no {
  width: 15px;
  flex: none;
  color: var(--muted-2);
  font: 8px/1 var(--font-mono);
}

.poi-icon {
  width: 30px;
  height: 30px;
  flex: none;
  display: grid;
  place-items: center;
  border: 1px solid var(--line);
  color: var(--gold);
  background: rgba(0, 0, 0, 0.18);
}

.poi-icon .icon {
  width: 15px;
  height: 15px;
}

.poi-copy {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.poi-copy strong {
  color: #ddd5c3;
  font: 500 12px/1.2 var(--font-body);
}

.poi-copy small {
  color: var(--muted-2);
  font: 8px/1.2 var(--font-mono);
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.poi.is-found .poi-copy small {
  color: var(--green);
}

.poi-state {
  display: grid;
  place-items: center;
  color: var(--gold);
}

.poi-state .icon {
  width: 14px;
  height: 14px;
}

.progress {
  margin-top: auto;
}

.progress-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: var(--muted-2);
  font: 8px/1 var(--font-mono);
  letter-spacing: 0.11em;
  text-transform: uppercase;
}

.progress-label b {
  color: var(--gold);
  font-weight: 400;
}

.progress-segments {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 4px;
  margin: 7px 0 15px;
}

.progress-segments span {
  height: 4px;
  background: rgba(255, 255, 255, 0.08);
}

.progress-segments span.on {
  background: var(--gold);
}

.progress-segments span.on.gun {
  background: var(--oxblood-bright);
}

.panel-actions {
  display: grid;
  gap: 7px;
}

.panel-actions .btn {
  width: 100%;
  min-height: 44px;
  font-size: 9px;
  padding: 0 12px;
}

/* == APPEND == */

files.patch:
Index: styles.css
===================================================================
--- styles.css
+++ styles.css
@@ -486,5 +486,1172 @@
   font-size: 8px;
   letter-spacing: 0.16em;
 }

+/* ------------------------------------------------------------
+   Office — the call
+   ------------------------------------------------------------ */
+
+.office {
+  display: grid;
+  gap: 26px;
+  align-items: center;
+}
+
+.office-art {
+  position: relative;
+  height: clamp(240px, 58vw, 340px);
+  overflow: hidden;
+  border: 1px solid var(--line-strong);
+  background:
+    radial-gradient(ellipse at 68% 28%, rgba(201, 168, 106, 0.1), transparent 44%),
+    linear-gradient(180deg, #22241d 0%, #131510 68%, #0b0c09 100%);
+  box-shadow: var(--shadow-lg), inset 0 0 90px rgba(0, 0, 0, 0.65);
+  isolation: isolate;
+}
+
+.office-art::before {
+  content: '';
+  position: absolute;
+  inset: 0;
+  background-image: repeating-linear-gradient(
+    90deg,
+    transparent 0 53px,
+    rgba(0, 0, 0, 0.16) 54px,
+    transparent 55px
+  );
+  opacity: 0.7;
+  z-index: 0;
+}
+
+.office-art::after {
+  content: '';
+  position: absolute;
+  inset: 0;
+  z-index: 9;
+  pointer-events: none;
+  background:
+    linear-gradient(180deg, rgba(0, 0, 0, 0.35), transparent 26%),
+    radial-gradient(ellipse at 48% 52%, transparent 38%, rgba(4, 5, 4, 0.55) 100%);
+}
+
+.office-window {
+  position: absolute;
+  left: 9%;
+  top: 10%;
+  width: 55%;
+  height: 54%;
+  overflow: hidden;
+  border: 6px solid #2a251c;
+  background: linear-gradient(180deg, #0a1317 0%, #14282e 56%, #1d2c2b 100%);
+  box-shadow:
+    inset 0 0 36px rgba(0, 0, 0, 0.9),
+    0 12px 26px rgba(0, 0, 0, 0.55),
+    0 0 0 1px rgba(201, 168, 106, 0.14);
+  z-index: 2;
+}
+
+.city-glow {
+  position: absolute;
+  inset: auto 0 0;
+  height: 48%;
+  background:
+    radial-gradient(ellipse at 55% 100%, rgba(214, 170, 92, 0.34), transparent 62%),
+    linear-gradient(180deg, transparent, rgba(6, 10, 10, 0.72));
+}
+
+.city {
+  position: absolute;
+  left: 0;
+  right: 0;
+  bottom: 0;
+  height: 39%;
+  background: #050a0b;
+  clip-path: polygon(
+    0 46%, 7% 46%, 7% 28%, 13% 28%, 13% 55%, 21% 55%, 21% 37%, 27% 37%,
+    27% 62%, 36% 62%, 36% 25%, 44% 25%, 44% 54%, 53% 54%, 53% 34%, 61% 34%,
+    61% 60%, 70% 60%, 70% 42%, 78% 42%, 78% 57%, 87% 57%, 87% 31%, 94% 31%,
+    94% 60%, 100% 60%, 100% 100%, 0 100%
+  );
+  opacity: 0.92;
+}
+
+.city::after {
+  content: '';
+  position: absolute;
+  inset: 0;
+  background-image: radial-gradient(circle, rgba(226, 188, 116, 0.75) 1px, transparent 1.4px);
+  background-size: 13px 17px;
+  opacity: 0.38;
+  mask-image: linear-gradient(transparent 25%, #000);
+  -webkit-mask-image: linear-gradient(transparent 25%, #000);
+}
+
+.blinds {
+  position: absolute;
+  inset: 0;
+  z-index: 2;
+  background-image: repeating-linear-gradient(
+    180deg,
+    rgba(7, 9, 8, 0.72) 0 8px,
+    transparent 8px 19px
+  );
+  opacity: 0.42;
+}
+
+.rain-glass {
+  position: absolute;
+  inset: -20%;
+  z-index: 3;
+  background-image: repeating-linear-gradient(
+    102deg,
+    transparent 0 13px,
+    rgba(193, 220, 223, 0.32) 14px,
+    transparent 15px 34px
+  );
+  background-size: 150px 250px;
+  animation: rainfall 1.2s linear infinite;
+  opacity: 0.7;
+}
+
+.window-bar {
+  position: absolute;
+  z-index: 4;
+  background: #241f17;
+  box-shadow: 0 0 0 1px rgba(201, 168, 106, 0.1);
+}
+
+.window-bar.v {
+  top: 0;
+  bottom: 0;
+  left: 49%;
+  width: 5px;
+}
+
+.window-bar.h {
+  left: 0;
+  right: 0;
+  top: 46%;
+  height: 5px;
+}
+
+.window-sill {
+  position: absolute;
+  left: -8%;
+  right: -8%;
+  bottom: -8px;
+  height: 11px;
+  background: linear-gradient(180deg, #4b4030, #231e16);
+  box-shadow: 0 5px 12px rgba(0, 0, 0, 0.6);
+  z-index: 5;
+}
+
+.wall-art {
+  position: absolute;
+  right: 13%;
+  top: 11%;
+  width: 15%;
+  height: 19%;
+  border: 2px solid #4e4231;
+  background: linear-gradient(150deg, #26241c, #11130f);
+  transform: rotate(2deg);
+  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.5);
+  z-index: 2;
+}
+
+.wall-art::before {
+  content: '';
+  position: absolute;
+  inset: 10%;
+  border: 1px solid rgba(201, 168, 106, 0.18);
+  background: repeating-linear-gradient(
+    180deg,
+    transparent 0 5px,
+    rgba(201, 168, 106, 0.18) 6px,
+    transparent 7px
+  );
+}
+
+.office-desk {
+  position: absolute;
+  left: -3%;
+  right: -3%;
+  bottom: -2%;
+  height: 34%;
+  background:
+    repeating-linear-gradient(91deg, rgba(255, 255, 255, 0.025) 0 2px, transparent 2px 38px),
+    linear-gradient(180deg, #56402b 0%, #332418 38%, #1b130e 100%);
+  border-top: 1px solid #8a6940;
+  box-shadow:
+    0 -10px 34px rgba(0, 0, 0, 0.55),
+    inset 0 2px 0 rgba(180, 140, 86, 0.4);
+  z-index: 4;
+}
+
+.office-glow {
+  position: absolute;
+  left: 4%;
+  bottom: 20%;
+  width: 50%;
+  height: 60%;
+  z-index: 3;
+  pointer-events: none;
+  background: radial-gradient(ellipse at 24% 72%, rgba(239, 193, 112, 0.24), transparent 62%);
+  mix-blend-mode: screen;
+}
+
+.desk-lamp {
+  position: absolute;
+  left: 16%;
+  bottom: 31%;
+  width: 62px;
+  height: 86px;
+  z-index: 5;
+}
+
+.desk-lamp::before {
+  content: '';
+  position: absolute;
+  left: 50%;
+  bottom: 0;
+  width: 5px;
+  height: 48px;
+  background: linear-gradient(180deg, #7c6744, #33291b);
+  transform: translateX(-50%);
+}
+
+.desk-lamp::after {
+  content: '';
+  position: absolute;
+  left: 0;
+  top: 0;
+  width: 62px;
+  height: 32px;
+  background: linear-gradient(180deg, #d9b477 0%, #8e6a3d 55%, #4c3822 100%);
+  clip-path: polygon(26% 0, 74% 0, 100% 100%, 0 100%);
+  box-shadow: 0 -4px 30px rgba(240, 198, 118, 0.4);
+}
+
+.desk-phone {
+  position: absolute;
+  right: 16%;
+  bottom: 31%;
+  width: 58px;
+  height: 32px;
+  z-index: 6;
+  border: 2px solid #514631;
+  background: #171813;
+  transform: perspective(110px) rotateX(18deg);
+  box-shadow: 0 8px 14px rgba(0, 0, 0, 0.55);
+}
+
+.desk-phone::before {
+  content: '';
+  position: absolute;
+  left: 50%;
+  top: 48%;
+  width: 23px;
+  height: 23px;
+  border-radius: 50%;
+  transform: translate(-50%, -50%);
+  background: repeating-radial-gradient(circle, #3a3529 0 2px, #151611 3px 4px);
+}
+
+.desk-phone::after {
+  content: '';
+  position: absolute;
+  left: -6px;
+  top: -14px;
+  width: 66px;
+  height: 13px;
+  border-radius: 7px;
+  background: linear-gradient(180deg, #353428, #171813);
+  box-shadow: 0 3px 0 #0a0b08;
+  animation: phone-shiver 4s ease-in-out infinite;
+}
+
+@keyframes phone-shiver {
+  0%, 88%, 100% { transform: rotate(0); }
+  90% { transform: rotate(-2deg); }
+  92% { transform: rotate(2deg); }
+  94% { transform: rotate(-1deg); }
+}
+
+.desk-paper {
+  position: absolute;
+  left: 38%;
+  bottom: 25%;
+  width: 14%;
+  height: 7%;
+  z-index: 5;
+  background: linear-gradient(150deg, #d9ceb4, #a99d82);
+  transform: rotate(-7deg);
+  box-shadow: 0 5px 9px rgba(0, 0, 0, 0.5);
+}
+
+.desk-paper.b {
+  left: 47%;
+  bottom: 21%;
+  width: 11%;
+  transform: rotate(5deg);
+  opacity: 0.85;
+}
+
+.desk-glass {
+  position: absolute;
+  right: 29%;
+  bottom: 26%;
+  width: 15px;
+  height: 22px;
+  z-index: 6;
+  border: 1px solid rgba(226, 235, 229, 0.35);
+  border-radius: 1px 1px 4px 4px;
+  background: linear-gradient(90deg, rgba(255, 255, 255, 0.17), rgba(255, 255, 255, 0.02));
+  box-shadow: 0 4px 7px rgba(0, 0, 0, 0.4);
+}
+
+.ashtray {
+  position: absolute;
+  right: 7%;
+  bottom: 24%;
+  width: 30px;
+  height: 10px;
+  z-index: 6;
+  border-radius: 50%;
+  background: radial-gradient(ellipse, #3e3427 0 35%, #17140f 40% 100%);
+  box-shadow: 0 3px 5px #0008;
+}
+
+.smoke {
+  position: absolute;
+  right: 10%;
+  bottom: 28%;
+  width: 4px;
+  height: 72px;
+  z-index: 5;
+  border-radius: 50%;
+  background: linear-gradient(180deg, transparent, rgba(214, 214, 202, 0.24));
+  filter: blur(4px);
+  animation: smoke 6s ease-in-out infinite;
+  transform-origin: bottom;
+}
+
+@keyframes smoke {
+  0%, 100% { opacity: 0.2; transform: translateX(0) scaleY(0.9); }
+  50% { opacity: 0.55; transform: translateX(9px) scaleY(1.12); }
+}
+
+.art-chip {
+  position: absolute;
+  top: 12px;
+  right: 12px;
+  z-index: 10;
+  display: flex;
+  align-items: center;
+  gap: 6px;
+  padding: 6px 8px;
+  border: 1px solid rgba(236, 227, 207, 0.16);
+  background: rgba(8, 9, 7, 0.68);
+  backdrop-filter: blur(6px);
+  -webkit-backdrop-filter: blur(6px);
+  color: #d9d1bd;
+  font: 8px/1 var(--font-mono);
+  letter-spacing: 0.11em;
+  text-transform: uppercase;
+}
+
+.art-chip b {
+  color: var(--gold-bright);
+  font-weight: 400;
+}
+
+.art-weather {
+  position: absolute;
+  left: 13px;
+  bottom: 13px;
+  z-index: 10;
+  color: rgba(236, 227, 207, 0.55);
+  font: 8px/1 var(--font-mono);
+  letter-spacing: 0.13em;
+}
+
+.office-copy {
+  max-width: 560px;
+}
+
+.office-copy .lede {
+  margin-bottom: 20px;
+}
+
+.callout {
+  padding: 14px 16px;
+  margin-bottom: 18px;
+  border-left: 2px solid var(--gold);
+  background: linear-gradient(120deg, rgba(201, 168, 106, 0.09), rgba(255, 255, 255, 0.012));
+}
+
+.callout-head {
+  display: flex;
+  align-items: center;
+  gap: 10px;
