  bottom: 27%;
  width: 36%;
  height: 29%;
  transform: rotate(5deg);
  background: linear-gradient(160deg, #ded3bb, #bdb094);
}

.cu-torn {
  position: absolute;
  left: 23%;
  bottom: 11%;
  z-index: 4;
  width: 35%;
  height: 12%;
  transform: rotate(-4deg);
  background: #d9ccb1;
  clip-path: polygon(0 20%, 100% 0, 97% 100%, 2% 86%);
  box-shadow: 0 8px 14px rgba(0, 0, 0, 0.4);
}

.cu-torn::after {
  content: '';
  position: absolute;
  inset: 34% 9% 52%;
  background: repeating-linear-gradient(90deg, rgba(50, 44, 35, 0.55) 0 12px, transparent 12px 17px);
}

.cu-glass {
  position: absolute;
  right: 16%;
  bottom: 11%;
  z-index: 4;
  width: 44px;
  height: 60px;
  transform: rotate(4deg);
  border: 1px solid rgba(255, 255, 255, 0.34);
  border-radius: 2px 2px 9px 9px;
  background: linear-gradient(90deg, rgba(220, 232, 228, 0.27), rgba(255, 255, 255, 0.04));
  box-shadow: inset 0 0 18px rgba(255, 255, 255, 0.1), 0 12px 20px rgba(0, 0, 0, 0.5);
}

.cu-glass::after {
  content: '';
  position: absolute;
  left: 5px;
  right: 5px;
  bottom: 7px;
  height: 21px;
  border-radius: 1px 1px 5px 5px;
  background: rgba(160, 94, 43, 0.45);
}

.cu-magnifier {
  position: absolute;
  left: 7%;
  top: 14%;
  z-index: 4;
  width: 74px;
  height: 74px;
  transform: rotate(-8deg);
  border: 5px solid #8b6c3d;
  border-radius: 50%;
  box-shadow: inset 0 0 22px rgba(200, 220, 220, 0.1), 0 10px 20px rgba(0, 0, 0, 0.5);
  opacity: 0.9;
}

.cu-magnifier::after {
  content: '';
  position: absolute;
  right: -26px;
  bottom: -20px;
  width: 11px;
  height: 52px;
  transform: rotate(-40deg);
  border-radius: 6px;
  background: linear-gradient(#705832, #312516);
}

.cu-lamp {
  position: absolute;
  right: 0;
  top: 0;
  z-index: 2;
  width: 60%;
  height: 80%;
  pointer-events: none;
  background: radial-gradient(ellipse at 72% 8%, rgba(243, 202, 124, 0.34), transparent 62%);
}

/* Window close-up */

.closeup-window {
  background: linear-gradient(180deg, #081014, #122126 60%, #1a292b);
}

.cu-night {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 63% 18%, rgba(148, 183, 189, 0.12), transparent 50%),
    linear-gradient(180deg, #081014, #132329 55%, #1b2b2d);
}

.cu-city {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 12%;
  height: 34%;
  background: linear-gradient(180deg, transparent, #050a0b 38%);
  clip-path: polygon(
    0 45%, 8% 46%, 8% 28%, 14% 28%, 14% 52%, 22% 52%, 22% 36%, 28% 36%,
    28% 60%, 38% 60%, 38% 22%, 46% 22%, 46% 50%, 55% 50%, 55% 32%, 63% 32%,
    63% 58%, 72% 58%, 72% 40%, 80% 40%, 80% 54%, 88% 54%, 88% 30%, 95% 30%,
    95% 58%, 100% 58%, 100% 100%, 0 100%
  );
}

.cu-city::after {
  content: '';
  position: absolute;
  inset: 0;
  background-image: radial-gradient(circle, rgba(229, 190, 118, 0.7) 1px, transparent 1.5px);
  background-size: 14px 18px;
  opacity: 0.55;
  mask-image: linear-gradient(transparent, #000 50%);
  -webkit-mask-image: linear-gradient(transparent, #000 50%);
}

.cu-curtain {
  position: absolute;
  top: -4%;
  bottom: -4%;
  width: 17%;
  z-index: 4;
  background: repeating-linear-gradient(90deg, #1a1c17 0 12px, #272a22 13px 22px, #121410 23px 36px);
  box-shadow: 0 0 24px rgba(0, 0, 0, 0.6);
}

.cu-curtain.left { left: -2%; }
.cu-curtain.right { right: -2%; }

.cu-window-frame {
  position: absolute;
  inset: 5% 6%;
  z-index: 2;
  border: 9px solid #2c2519;
  box-shadow: inset 0 0 38px rgba(0, 0, 0, 0.65), 0 0 0 1px #5f4d32;
}

.cu-window-frame::before,
.cu-window-frame::after {
  content: '';
  position: absolute;
  z-index: 3;
  background: #2c2519;
  box-shadow: 0 0 0 1px rgba(201, 168, 106, 0.1);
}

.cu-window-frame::before {
  left: 49%;
  top: 0;
  bottom: 0;
  width: 6px;
}

.cu-window-frame::after {
  left: 0;
  right: 0;
  top: 48%;
  height: 6px;
}

.cu-rain {
  position: absolute;
  inset: 4% 5%;
  z-index: 3;
  background-image: repeating-linear-gradient(
    102deg,
    transparent 0 12px,
    rgba(198, 224, 226, 0.32) 13px,
    transparent 14px 31px
  );
  background-size: 135px 230px;
  animation: rainfall 1.3s linear infinite;
  opacity: 0.75;
}

.cu-sill {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 3%;
  z-index: 4;
  height: 8%;
  border-top: 1px solid #8a6c43;
  background: linear-gradient(180deg, #4a3c29, #241c13);
  box-shadow: 0 8px 18px rgba(0, 0, 0, 0.6);
}

.cu-latch {
  position: absolute;
  right: 20%;
  top: 51%;
  z-index: 5;
  width: 22px;
  height: 36px;
  border: 1px solid #b18b52;
  border-radius: 2px;
  background: linear-gradient(90deg, #7d6136, #d0ac70 45%, #6d522d);
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.6), 0 0 12px rgba(201, 168, 106, 0.18);
  transform: rotate(3deg);
}

.cu-smear {
  position: absolute;
  right: 16%;
  top: 47%;
  z-index: 5;
  width: 44px;
  height: 23px;
  border-radius: 50%;
  background: radial-gradient(ellipse, rgba(160, 88, 67, 0.55), transparent 68%);
  filter: blur(2px);
  transform: rotate(-18deg);
}

.cu-reflection {
  position: absolute;
  left: 10%;
  top: -20%;
  z-index: 3;
  width: 26%;
  height: 140%;
  transform: rotate(18deg);
  background: linear-gradient(90deg, transparent, rgba(220, 235, 235, 0.07), transparent);
}

/* Coat close-up */

.closeup-coat {
  background:
    radial-gradient(ellipse at 60% 0%, rgba(201, 168, 106, 0.14), transparent 52%),
    linear-gradient(160deg, #37342a, #151612 68%);
}

.cu-hook {
  position: absolute;
  left: 52%;
  top: 7%;
  z-index: 3;
  width: 26px;
  height: 52px;
  border-right: 4px solid #7d6a48;
  border-top: 4px solid #7d6a48;
  border-radius: 0 15px 0 0;
  transform: rotate(7deg);
  box-shadow: 2px -2px 8px rgba(0, 0, 0, 0.4);
}

.cu-coat {
  position: absolute;
  left: 29%;
  top: 17%;
  z-index: 2;
  width: 42%;
  height: 74%;
  background: linear-gradient(145deg, #3c3a31, #171813 70%);
  clip-path: polygon(30% 0, 70% 0, 96% 12%, 100% 46%, 86% 100%, 14% 100%, 0 46%, 4% 12%);
  filter: drop-shadow(0 18px 16px rgba(0, 0, 0, 0.5));
}

.cu-collar {
  position: absolute;
  left: 50%;
  top: -2%;
  width: 42%;
  height: 24%;
  transform: translateX(-50%);
  background: linear-gradient(160deg, #4b483c, #24251f);
  clip-path: polygon(50% 0, 100% 38%, 64% 100%, 36% 100%, 0 38%);
}

.cu-lapel {
  position: absolute;
  left: 50%;
  top: 12%;
  width: 2px;
  height: 56%;
  background: #565246;
  transform: translateX(-50%);
}

.cu-pocket {
  position: absolute;
  left: 52%;
  bottom: 18%;
  width: 38%;
  height: 19%;
  border: 1px solid #555143;
  background: rgba(10, 11, 9, 0.3);
  transform: rotate(-2deg);
}

.cu-cufflink {
  position: absolute;
  left: 63%;
  bottom: 27%;
  z-index: 4;
  width: 13px;
  height: 13px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #f2d99f, #b08b4d 50%, #5b421e);
  box-shadow: 0 0 10px rgba(232, 205, 146, 0.7), 0 2px 4px #000;
}

.cu-coat-light {
  position: absolute;
  left: 0;
  top: 0;
  z-index: 3;
  width: 60%;
  height: 90%;
  pointer-events: none;
  background: radial-gradient(ellipse at 20% 12%, rgba(223, 209, 177, 0.14), transparent 62%);
}

.cu-rain-beads {
  position: absolute;
  inset: 0;
  z-index: 3;
  opacity: 0.45;
  background-image:
    radial-gradient(circle, rgba(210, 228, 228, 0.7) 1px, transparent 1.5px),
    radial-gradient(circle, rgba(210, 228, 228, 0.45) 1px, transparent 1.5px);
  background-size: 27px 31px, 19px 23px;
  background-position: 3px 7px, 11px 3px;
  mask-image: radial-gradient(ellipse at 55% 55%, #000 20%, transparent 66%);
  -webkit-mask-image: radial-gradient(ellipse at 55% 55%, #000 20%, transparent 66%);
}

/* Body close-up */

.closeup-body {
  background: linear-gradient(160deg, #383228, #211d17);
}

.cu-floor {
  position: absolute;
  inset: 0;
  background:
    repeating-linear-gradient(92deg, #332d23 0 58px, #2a251d 58px 61px),
    repeating-linear-gradient(180deg, rgba(255, 255, 255, 0.02) 0 1px, transparent 1px 44px);
}

.cu-body-svg {
  position: absolute;
  inset: 0;
  z-index: 2;
  width: 100%;
  height: 100%;
}

.cu-tag {
  position: absolute;
  z-index: 4;
  width: 26px;
  height: 34px;
  background: linear-gradient(160deg, #dfd0a9, #b6a47c);
  border: 1px solid #8e7c56;
  box-shadow: 0 5px 9px rgba(0, 0, 0, 0.45);
  display: grid;
  place-items: center;
  color: #463a24;
  font: 500 10px var(--font-mono);
  transform: rotate(11deg);
}

.cu-tag::before {
  content: '';
  position: absolute;
  left: 50%;
  top: -7px;
  width: 1px;
  height: 7px;
  background: #8e7c56;
}

.cu-tag.a { left: 18%; top: 23%; }
.cu-tag.b { right: 17%; bottom: 18%; transform: rotate(-14deg); }

.cu-ruler {
  position: absolute;
  right: 7%;
  top: 12%;
  z-index: 4;
  width: 10px;
  height: 58%;
  transform: rotate(6deg);
  background:
    repeating-linear-gradient(180deg, transparent 0 8px, rgba(43, 33, 20, 0.7) 8px 9px),
    linear-gradient(90deg, #d3bb87, #9e7c47);
  box-shadow: 0 5px 9px rgba(0, 0, 0, 0.4);
}

.cu-flash {
  position: absolute;
  inset: 0;
  z-index: 3;
  background: radial-gradient(ellipse at 12% 0%, rgba(235, 240, 228, 0.16), transparent 45%);
}

/* Zoom copy */

.zoom-copy {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 22px 20px 26px;
  background: linear-gradient(180deg, #1c1e18, #131510);
}

.zoom-copy h1 {
  margin: 9px 0 13px;
  color: #f0e8d7;
  font: 500 clamp(1.9rem, 7vw, 2.8rem) / 1.04 var(--font-display);
  letter-spacing: -0.025em;
}

.clue-dots {
  display: flex;
  gap: 5px;
  margin-bottom: 15px;
}

.clue-dots i {
  width: 21px;
  height: 3px;
  background: rgba(255, 255, 255, 0.1);
}

.clue-dots i.on {
  background: var(--gold);
}

.clue-dots i.on.gun {
  background: var(--oxblood-bright);
}

.clue-text {
  margin-bottom: 16px;
  padding-left: 13px;
  border-left: 1px solid rgba(201, 168, 106, 0.45);
  color: #d6d0c1;
  font-size: 15px;
  line-height: 1.62;
}

.clue-note {
  margin: -4px 0 16px;
  color: var(--gold-bright);
  font: italic 13px/1.5 var(--font-display);
}

.evidence-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-bottom: 20px;
}

.logged,
.gun-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 5px 8px;
  border: 1px solid rgba(143, 163, 133, 0.4);
  color: #c8d8c0;
  font: 8px/1 var(--font-mono);
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.logged .icon {
  width: 11px;
  height: 11px;
}

.gun-badge {
  border-color: rgba(217, 138, 123, 0.55);
  background: rgba(154, 68, 56, 0.15);
  color: #e6a194;
}

.zoom-actions {
  display: grid;
  gap: 8px;
  margin-top: auto;
}

.zoom-actions .btn {
  width: 100%;
}

/* == APPEND == */

