}

.suspect-card.selected::after {
  content: 'Prime suspect';
  position: absolute;
  top: 7px;
  right: -5px;
  z-index: 6;
  padding: 3px 5px;
  transform: rotate(4deg);
  border: 2px solid #8f3b31;
  background: #e2d3b4;
  color: #8f3b31;
  font: 700 7px/1 var(--font-mono);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.mugshot {
  position: relative;
  height: 108px;
  margin-bottom: 9px;
  overflow: hidden;
  border: 1px solid #16130d;
