}

.m-head {
  position: absolute;
  left: 50%;
  top: 25%;
  z-index: 2;
  width: 29px;
  height: 34px;
  margin-left: -14.5px;
  border-radius: 46% 46% 42% 42%;
  background: linear-gradient(180deg, #c7a07b, #8e6a4c);
}

.m-head::after {
  content: '';
  position: absolute;
  left: 22%;
  right: 22%;
  bottom: 22%;
  height: 2px;
  background: rgba(38, 27, 18, 0.55);
}

.m-hat {
  position: absolute;
  left: 50%;
  top: 8%;
  z-index: 3;
  width: 52px;
  height: 12px;
  margin-left: -26px;
  border-radius: 50%;
  background: #171712;
  transform: rotate(-4deg);
}

.m-hat::before {
  content: '';
  position: absolute;
  left: 11px;
  bottom: 4px;
  width: 30px;
  height: 19px;
  border-radius: 6px 6px 2px 2px;
  background: linear-gradient(160deg, #2b2a22, #121310);
  transform: rotate(2deg);
}

.m-neck {
  position: absolute;
  left: 50%;
  top: 51%;
  z-index: 1;
  width: 14px;
  height: 13px;
  margin-left: -7px;
  background: linear-gradient(180deg, #8f6a4c, #5b422e);
}

.m-shoulders {
  position: absolute;
  left: 50%;
  bottom: -8%;
  z-index: 1;
