/* ------------------------------------------------------------
   Accusation sheet
   ------------------------------------------------------------ */

.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: grid;
  place-items: center;
  padding: 18px;
  background: rgba(3, 4, 3, 0.8);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  animation: fade-in 0.2s ease both;
}

@keyframes fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

.modal {
  position: relative;
  width: 100%;
  max-width: 420px;
  max-height: calc(100dvh - 36px);
  overflow-y: auto;
  padding: 25px 21px 19px;
  border: 1px solid #baa981;
  background: linear-gradient(165deg, #eee4cf, #d8c9ab);
  color: #251f15;
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.7);
  animation: modal-in 0.3s var(--ease) both;
}

@keyframes modal-in {
  from { opacity: 0; transform: translateY(14px) scale(0.98); }
  to { opacity: 1; transform: none; }
}

.modal::before {
  content: '';
  position: absolute;
  top: -6px;
  left: 50%;
  width: 11px;
  height: 11px;
  margin-left: -5.5px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #f0d49a, #8f6a32 60%, #3a2a12);
  box-shadow: 0 3px 5px rgba(0, 0, 0, 0.5);
}

.modal .eyebrow {
