}

.modal .eyebrow::before {
  background: #8a5a2f;
}

.modal h2 {
  margin: 8px 0 8px;
  color: #1f1a12;
  font: 500 clamp(1.75rem, 7vw, 2.25rem) / 1.04 var(--font-display);
  letter-spacing: -0.025em;
}

.modal > p {
  margin-bottom: 12px;
  color: #544a3a;
  font-size: 13px;
  line-height: 1.5;
}

.modal > p strong {
  color: #241d13;
}

.modal-facts {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px;
  margin: 12px 0;
}

.modal-facts div {
  padding: 7px 8px;
  border: 1px solid #b4a383;
}

.modal-facts span {
  display: block;
  color: #7a684c;
  font: 7.5px/1.2 var(--font-mono);
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.modal-facts strong {
  display: block;
  margin-top: 3px;
  color: #2b2418;
  font: 500 11px/1.3 var(--font-body);
}

.modal-alert {
  padding-left: 9px;
  border-left: 2px solid #983f33;
  color: #7d3028 !important;
  font-size: 11.5px !important;
}

.modal-actions {
  display: grid;
  gap: 7px;
  margin-top: 16px;
}

.modal-actions .btn {
  width: 100%;
  min-height: 46px;
  font-size: 9px;
}

.modal .btn-ghost {
  border-color: #9b896a;
  background: transparent;
  color: #3a3123;
}

.modal .btn-ghost:hover {
  border-color: #3a3123;
  background: rgba(58, 49, 35, 0.07);
  color: #241d13;
}

.modal-x {
  position: absolute;
  top: 9px;
  right: 9px;
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border: 0;
  background: transparent;
  color: #5b5040;
  cursor: pointer;
}

.modal-x:hover {
  color: #211b12;
}

.modal-x .icon {
  width: 16px;
  height: 16px;
}

/* ------------------------------------------------------------
   End of case
   ------------------------------------------------------------ */

.end {
  max-width: 760px;
  padding: 6px 0 20px;
  text-align: center;
}

.outcome-stamp {
  display: inline-block;
  margin-bottom: 17px;
  padding: 7px 11px;
  transform: rotate(-2deg);
  border: 2px solid;
  font: 700 8.5px/1 var(--font-mono);
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.end.is-win .outcome-stamp {
  border-color: var(--gold);
  color: var(--gold-bright);
}

.end.is-loss .outcome-stamp {
  border-color: var(--oxblood);
  color: var(--oxblood-bright);
}

.end .display {
  margin: 12px 0 13px;
}

.end.is-loss .display em {
  color: #d98a7b;
}

.end .lede {
  max-width: 48ch;
  margin: 0 auto 23px;
}

.case-summary {
  position: relative;
  max-width: 520px;
  margin: 0 auto 23px;
  padding: 18px 17px;
  transform: rotate(-0.4deg);
  border: 1px solid #b7a887;
  background: linear-gradient(165deg, #ece2cc, #d9cbb0);
  color: #2a2419;
  text-align: left;
  box-shadow: 0 22px 45px rgba(0, 0, 0, 0.45);
}

.summary-head {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 1px solid #b7a887;
  color: #75664d;
  font: 7.5px/1.3 var(--font-mono);
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.summary-head span:last-child {
  color: #983f33;
}

.case-summary dl {
  display: grid;
  gap: 9px;
}

.case-summary dl div {
  display: grid;
  grid-template-columns: 78px minmax(0, 1fr);
  gap: 9px;
  align-items: baseline;
}

.case-summary dt {
  color: #79694f;
  font: 7.5px/1.3 var(--font-mono);
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.case-summary dd {
  color: #2b2418;
  font: 500 13px/1.35 var(--font-body);
}

.case-summary dd em {
  color: #1f1a12;
  font: italic 15px/1.2 var(--font-display);
}

.summary-note {
  margin-top: 11px;
  padding-top: 9px;
  border-top: 1px dashed #b1a080;
  color: #6c352d;
  font-size: 10.5px;
  line-height: 1.45;
}

.end-actions {
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-width: 420px;
  margin: 0 auto;
}

.end-actions .btn {
  width: 100%;
}

/* ------------------------------------------------------------
   Responsive upgrades
   ------------------------------------------------------------ */

@media (min-width: 380px) {
  .ghost-btn {
    padding: 0 13px;
  }

  .footer span:last-child {
    display: inline;
  }
}

@media (min-width: 600px) {
  .app-shell {
    padding: 0 24px;
  }

  .topbar {
    margin: 0 -24px;
    padding: 8px 24px;
    min-height: 70px;
  }

  .brand-mark {
    width: 40px;
    height: 40px;
    font-size: 27px;
  }

  .brand-name {
    font-size: 12px;
  }

  .brand-sub {
    display: block;
  }

  .game-frame {
    padding: 32px 0 42px;
  }

  .office-art {
    height: 340px;
  }

  .office-copy > .btn {
    width: auto;
    min-width: 240px;
  }

  .facts strong {
    font-size: 15px;
  }

  .scene-art {
    min-height: 420px;
  }

  .scene-panel {
    padding: 22px;
  }

  .poi-list {
    grid-template-columns: 1fr 1fr;
  }

  .poi {
    min-height: 58px;
  }

  .panel-actions {
    grid-template-columns: 1fr 1fr;
  }

  .board-panel {
    padding: 17px;
  }

  .evidence-list {
    gap: 15px;
  }

  .evidence-card {
    padding: 18px 18px 16px;
  }

  .mugshot {
    height: 122px;
  }

  .modal {
    padding: 28px 26px 22px;
  }

  .modal-actions {
    grid-template-columns: 1fr 1fr;
  }

  .modal-actions .btn {
    min-height: 48px;
  }

  .end-actions {
    flex-direction: row;
    justify-content: center;
    max-width: none;
  }

  .end-actions .btn {
    width: auto;
    min-width: 190px;
  }
}

@media (min-width: 900px) {
  .app-shell {
    padding: 0 34px;
  }

  .topbar {
    margin: 0 -34px;
    padding: 8px 34px;
    min-height: 80px;
  }

  .top-meta {
    display: flex;
  }

  .brand-name {
    font-size: 13px;
    letter-spacing: 0.18em;
  }

  .ghost-btn {
    min-height: 38px;
  }

  .game-frame {
    padding: 42px 0 52px;
  }

  .office {
    grid-template-columns: minmax(0, 1.08fr) minmax(0, 0.92fr);
    gap: 48px;
  }

  .office-art {
    height: clamp(430px, 44vw, 530px);
  }

  .office-copy .display {
    font-size: clamp(3.7rem, 5.1vw, 4.7rem);
  }

  .office-copy .lede {
    font-size: 15px;
  }

  .callout p {
    font-size: 17px;
  }

  .scene .page-head,
  .board .page-head {
    flex-direction: row;
    align-items: flex-end;
    justify-content: space-between;
    gap: 24px;
    margin-bottom: 24px;
  }

  .location {
    justify-content: flex-end;
    max-width: 330px;
    text-align: right;
  }

  .location small {
    text-align: right;
  }

  .scene-grid {
    grid-template-columns: minmax(0, 1.7fr) minmax(300px, 0.86fr);
    gap: 18px;
    align-items: stretch;
  }

  .scene-art {
    min-height: 540px;
  }

  .hotspot-dot {
    width: 52px;
    height: 52px;
  }

  .hotspot-tag {
    display: block;
    opacity: 0;
    transform: translateY(-3px);
    transition: opacity 0.2s, transform 0.2s;
  }

  .hotspot:hover .hotspot-tag {
    opacity: 1;
    transform: none;
  }

  .scene-panel {
    padding: 26px;
  }

  .poi-list {
    grid-template-columns: 1fr;
  }

  .panel-actions {
    grid-template-columns: 1fr;
  }

  .zoom {
    grid-template-columns: minmax(0, 1.15fr) minmax(0, 0.85fr);
    min-height: 540px;
  }

  .zoom-art {
    min-height: 540px;
  }

  .zoom-copy {
    padding: 38px 32px;
  }

  .board-grid {
    grid-template-columns: minmax(0, 0.94fr) minmax(0, 1.06fr);
    gap: 18px;
    align-items: start;
  }

  .suspect-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .board-actions {
    position: static;
    flex-direction: row;
    align-items: center;
    gap: 12px;
    margin-top: 18px;
    padding: 0;
    border: 0;
    background: none;
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
    box-shadow: none;
  }

  .board-actions .hint {
    order: 0;
    flex: 1;
    padding: 0 8px;
    text-align: left;
  }

  .board-actions .btn {
    width: auto;
    min-height: 50px;
    padding: 0 20px;
  }

  .case-summary {
    padding: 20px 22px;
  }

  .end .display {
    font-size: clamp(3.4rem, 6vw, 4.6rem);
  }
}

@media (min-width: 1120px) {
  .office {
    gap: 64px;
  }

  .office-art {
    height: 530px;
  }

  .scene-art {
    min-height: 590px;
  }

  .zoom,
  .zoom-art {
    min-height: 580px;
  }

  .suspect-card {
    padding: 11px;
  }
}

@media (max-width: 359px) {
  .brand-lockup {
    display: none;
  }

  .brand-mark {
    width: 34px;
    height: 34px;
  }

  .facts {
    grid-template-columns: 1fr;
    gap: 12px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
}

