Index: styles.css
===================================================================
--- styles.css
+++ styles.css
@@ -2255,5 +2255,1101 @@
 .zoom-actions .btn {
   width: 100%;
 }

-/* == APPEND == */
+/* ------------------------------------------------------------
+   Evidence board
+   ------------------------------------------------------------ */
+
+.board-head {
+  flex-direction: row;
+  align-items: flex-end;
+  justify-content: space-between;
+  gap: 14px;
+}
+
+.board-head h1 {
+  font-size: clamp(1.9rem, 7vw, 3.3rem);
+}
+
+.case-stamp {
+  flex: none;
+  margin-bottom: 4px;
+  padding: 7px 9px;
+  transform: rotate(-3deg);
+  border: 2px solid var(--oxblood);
+  color: var(--oxblood-bright);
+  font: 700 8px/1 var(--font-mono);
+  letter-spacing: 0.15em;
+  text-transform: uppercase;
+  opacity: 0.9;
+}
+
+.case-stamp.is-gun {
+  border-color: var(--gold);
+  color: var(--gold-bright);
+}
+
+.board-grid {
+  display: grid;
+  gap: 13px;
+}
+
+.board-panel {
+  position: relative;
+  padding: 15px;
+  border: 1px solid var(--line-strong);
+  background:
+    radial-gradient(ellipse at 18% 8%, rgba(201, 168, 106, 0.055), transparent 42%),
+    linear-gradient(180deg, #1a1c16, #121410);
+  box-shadow: inset 0 0 45px rgba(0, 0, 0, 0.45), 0 20px 50px rgba(0, 0, 0, 0.28);
+}
+
+.board-panel::before {
+  content: '';
+  position: absolute;
+  inset: 5px;
+  border: 1px solid rgba(255, 255, 255, 0.025);
+  pointer-events: none;
+}
+
+.panel-head {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 10px;
+  margin-bottom: 15px;
+  padding-bottom: 10px;
+  border-bottom: 1px solid var(--line);
+  color: #d2ccbb;
+  font: 8.5px/1.3 var(--font-mono);
+  letter-spacing: 0.15em;
+  text-transform: uppercase;
+}
+
+.panel-head span:last-child {
+  color: var(--muted-2);
+}
+
+.evidence-list {
+  display: grid;
+  gap: 13px;
+}
+
+.evidence-card {
+  --tilt: -0.7deg;
+  position: relative;
+  padding: 16px 15px 15px;
+  transform: rotate(var(--tilt));
+  border: 1px solid #b7a887;
+  background: linear-gradient(160deg, #eee5d1, #d9cdb4);
+  color: var(--paper-ink);
+  box-shadow: 0 16px 26px rgba(0, 0, 0, 0.38);
+}
+
+.evidence-card:nth-child(2) { --tilt: 0.8deg; }
+.evidence-card:nth-child(3) { --tilt: -0.45deg; }
+.evidence-card:nth-child(4) { --tilt: 0.55deg; }
+
+.pin {
+  position: absolute;
+  top: -5px;
+  left: 50%;
+  width: 10px;
+  height: 10px;
+  margin-left: -5px;
+  border-radius: 50%;
+  background: radial-gradient(circle at 35% 30%, #f0d49a, #8f6a32 60%, #3a2a12);
+  box-shadow: 0 3px 5px rgba(0, 0, 0, 0.6);
+  z-index: 2;
+}
+
+.evidence-top {
+  display: flex;
+  justify-content: space-between;
+  gap: 8px;
+  margin-bottom: 6px;
+  color: #6d6250;
+  font: 7.5px/1.3 var(--font-mono);
+  letter-spacing: 0.12em;
+  text-transform: uppercase;
+}
+
+.evidence-card h3 {
+  margin-bottom: 5px;
+  color: #211d15;
+  font: 600 17px/1.15 var(--font-display);
+  letter-spacing: -0.01em;
+  padding-right: 10px;
+}
+
+.evidence-card p {
+  color: #4c4538;
+  font-size: 11.5px;
+  line-height: 1.5;
+}
+
+.evidence-card.is-gun {
+  background: linear-gradient(160deg, #f2e5cd, #dfcdae);
+}
+
+.evidence-card.is-gun p {
+  padding-right: 18px;
+}
+
+.gun-stamp {
+  position: absolute;
+  right: 9px;
+  bottom: 9px;
+  padding: 3px 5px;
+  transform: rotate(-7deg);
+  border: 2px solid #983f33;
+  background: rgba(255, 248, 235, 0.22);
+  color: #983f33;
+  font: 700 7px/1 var(--font-mono);
+  letter-spacing: 0.1em;
+  text-transform: uppercase;
+  opacity: 0.88;
+}
+
+.empty-evidence {
+  position: relative;
+  min-height: 178px;
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  justify-content: center;
+  gap: 6px;
+  padding: 20px;
+  border: 1px dashed rgba(201, 168, 106, 0.26);
+  background: rgba(0, 0, 0, 0.12);
+  text-align: center;
+}
+
+.empty-evidence .pin {
+  top: 12px;
+}
+
+.empty-evidence .icon {
+  width: 23px;
+  height: 23px;
+  color: var(--muted-2);
+}
+
+.empty-evidence strong {
+  color: #cfc6b0;
+  font: 500 14px/1.2 var(--font-display);
+}
+
+.empty-evidence p {
+  color: var(--muted-2);
+  font: 8px/1.5 var(--font-mono);
+  letter-spacing: 0.09em;
+  text-transform: uppercase;
+}
+
+.suspect-grid {
+  display: grid;
+  grid-template-columns: repeat(auto-fit, minmax(142px, 1fr));
+  gap: 10px;
+}
+
+.suspect-card {
+  position: relative;
+  display: flex;
+  flex-direction: column;
+  padding: 10px;
+  border: 1px solid #a99a78;
+  background: linear-gradient(165deg, #d9cba9, #c3b18a);
+  color: #241f16;
+  box-shadow: 0 12px 22px rgba(0, 0, 0, 0.32);
+  transition: transform 0.2s, outline-color 0.2s;
+}
+
+.suspect-card.selected {
+  outline: 2px solid var(--gold);
+  outline-offset: 3px;
+  transform: translateY(-3px);
+}
+
+.suspect-card.selected::after {
+  content: 'Prime suspect';
+  position: absolute;
+  top: 7px;
+  right: -5px;
+  z-index: 6;
+  padding: 3px 5px;
+  transform: rotate(4deg);
+  border: 2px solid #8f3b31;
+  background: #e2d3b4;
+  color: #8f3b31;
+  font: 700 7px/1 var(--font-mono);
+  letter-spacing: 0.08em;
+  text-transform: uppercase;
+}
+
+.mugshot {
+  position: relative;
+  height: 108px;
+  margin-bottom: 9px;
+  overflow: hidden;
+  border: 1px solid #16130d;
+  background:
+    repeating-linear-gradient(0deg, transparent 0 17px, rgba(255, 255, 255, 0.035) 17px 18px),
+    linear-gradient(160deg, #2c2d27, #10110e);
+}
+
+.mugshot::after {
+  content: '';
+  position: absolute;
+  inset: 0;
+  z-index: 5;
+  background: radial-gradient(ellipse at 50% 30%, transparent 20%, rgba(0, 0, 0, 0.5));
+  box-shadow: inset 0 0 30px #000;
+  pointer-events: none;
+}
+
+.m-head {
+  position: absolute;
+  left: 50%;
+  top: 25%;
+  z-index: 2;
+  width: 29px;
+  height: 34px;
+  margin-left: -14.5px;
+  border-radius: 46% 46% 42% 42%;
+  background: linear-gradient(180deg, #c7a07b, #8e6a4c);
+}
+
+.m-head::after {
+  content: '';
+  position: absolute;
+  left: 22%;
+  right: 22%;
+  bottom: 22%;
+  height: 2px;
+  background: rgba(38, 27, 18, 0.55);
+}
+
+.m-hat {
+  position: absolute;
+  left: 50%;
+  top: 8%;
+  z-index: 3;
+  width: 52px;
+  height: 12px;
+  margin-left: -26px;
+  border-radius: 50%;
+  background: #171712;
+  transform: rotate(-4deg);
+}
+
+.m-hat::before {
+  content: '';
+  position: absolute;
+  left: 11px;
+  bottom: 4px;
+  width: 30px;
+  height: 19px;
+  border-radius: 6px 6px 2px 2px;
+  background: linear-gradient(160deg, #2b2a22, #121310);
+  transform: rotate(2deg);
+}
+
+.m-neck {
+  position: absolute;
+  left: 50%;
+  top: 51%;
+  z-index: 1;
+  width: 14px;
+  height: 13px;
+  margin-left: -7px;
+  background: linear-gradient(180deg, #8f6a4c, #5b422e);
+}
+
+.m-shoulders {
+  position: absolute;
+  left: 50%;
+  bottom: -8%;
+  z-index: 1;
+  width: 88%;
+  height: 42%;
+  margin-left: -44%;
+  background: linear-gradient(160deg, #3d3a30, #191a15);
+  clip-path: polygon(22% 0, 78% 0, 100% 100%, 0 100%);
+}
+
+.m-tie {
+  position: absolute;
+  left: 50%;
+  bottom: 0;
+  z-index: 2;
+  width: 8px;
+  height: 38%;
+  margin-left: -4px;
+  background: #5a2a24;
+  clip-path: polygon(50% 0, 100% 20%, 70% 100%, 30% 100%, 0 20%);
+}
+
+.mugshot.v2 .m-head {
+  background: linear-gradient(180deg, #b8875f, #77553b);
+  top: 26%;
+}
+
+.mugshot.v2 .m-hat {
+  transform: rotate(5deg);
+  top: 7%;
+}
+
+.mugshot.v2 .m-tie {
+  background: #334235;
+  width: 9px;
+}
+
+.mugshot.v3 .m-head {
+  background: linear-gradient(180deg, #d1a77f, #9d7656);
+}
+
+.mugshot.v3 .m-hat {
+  transform: rotate(-8deg);
+  border-radius: 42% 58% 50% 50%;
+}
+
+.mugshot.v3 .m-shoulders {
+  background: linear-gradient(160deg, #464239, #1d1e19);
+}
+
+.mugshot.v3 .m-tie {
+  background: #3e3a2c;
+}
+
+.suspect-top {
+  margin-bottom: 8px;
+}
+
+.suspect-card h3 {
+  color: #201b12;
+  font: 600 16px/1.1 var(--font-display);
+  letter-spacing: -0.01em;
+}
+
+.role {
+  display: block;
+  margin-top: 3px;
+  color: #6e5a34;
+  font: 7.5px/1.35 var(--font-mono);
+  letter-spacing: 0.08em;
+  text-transform: uppercase;
+}
+
+.suspect-card dl {
+  display: grid;
+  gap: 7px;
+  margin-bottom: 10px;
+}
+
+.suspect-card dl div {
+  display: grid;
+  gap: 1px;
+}
+
+.suspect-card dt {
+  color: #806a40;
+  font: 7.5px/1.2 var(--font-mono);
+  letter-spacing: 0.1em;
+  text-transform: uppercase;
+}
+
+.suspect-card dd {
+  color: #40392c;
+  font-size: 10.5px;
+  line-height: 1.35;
+}
+
+.select-suspect {
+  min-height: 39px;
+  width: 100%;
+  margin-top: auto;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  gap: 5px;
+  border: 1px solid #8e7a52;
+  background: rgba(36, 30, 20, 0.07);
+  color: #2c2417;
+  font: 500 8px/1 var(--font-mono);
+  letter-spacing: 0.09em;
+  text-transform: uppercase;
+  cursor: pointer;
+  transition: background 0.2s, color 0.2s, border-color 0.2s;
+}
+
+.select-suspect:hover {
+  border-color: #2a2418;
+  background: #2a2418;
+  color: #f0e5cc;
+}
+
+.select-suspect .icon {
+  width: 11px;
+  height: 11px;
+}
+
+.suspect-card.selected .select-suspect {
+  border-color: #2b2417;
+  background: #2b2417;
+  color: #f0e3c4;
+}
+
+.board-actions {
+  position: sticky;
+  bottom: calc(8px + env(safe-area-inset-bottom));
+  z-index: 30;
+  display: flex;
+  flex-direction: column;
+  gap: 9px;
