+}
+
+/* ------------------------------------------------------------
+   Accusation sheet
+   ------------------------------------------------------------ */
+
+.modal-backdrop {
+  position: fixed;
+  inset: 0;
+  z-index: 100;
+  display: grid;
+  place-items: center;
+  padding: 18px;
+  background: rgba(3, 4, 3, 0.8);
+  backdrop-filter: blur(8px);
