+  font-size: 11.5px !important;
+}
+
+.modal-actions {
+  display: grid;
+  gap: 7px;
+  margin-top: 16px;
+}
+
+.modal-actions .btn {
+  width: 100%;
+  min-height: 46px;
+  font-size: 9px;
+}
+
+.modal .btn-ghost {
