  await shot('mobile-board');

  const killer = await page.evaluate(() => current.killer.name);
  await page.locator(`[data-suspect="${killer}"]`).click();
  assert(await page.locator('.suspect-card.selected').count() === 1, 'selected suspect not highlighted');
  assert(await page.locator('[data-action="accuse"]').isEnabled(), 'accuse button disabled');
  await page.locator('[data-action="accuse"]').click();
  await page.waitForSelector('.modal');
  const modalText = (await page.locator('.modal').innerText()).toLowerCase();
  assert(modalText.includes('smoking gun') && modalText.includes('in hand'), 'modal missing smoking gun confirmation');
  await shot('mobile-accuse');
  await page.locator('[data-action="confirm-accuse"]').click();
  await page.waitForSelector('.end.is-win');
  await overflow('win');
  assert((await page.locator('.end').innerText()).toLowerCase().includes('case closed'), 'win ending missing');
  await shot('mobile-win');

  await page.locator('[data-action="new"]').click();
  await page.waitForSelector('.office');
  await page.locator('[data-action="head"]').click();
  for (const key of ['desk', 'window', 'coat', 'body']) {
    await page.locator(`.poi[data-object="${key}"]`).click();
    await page.waitForSelector('.zoom');
    await page.locator('[data-action="scene"]').click();
  }
  await page.locator('[data-action="board"]').click();
  const wrong2 = await page.evaluate(() => current.suspects.find(s => s.name !== current.killer.name).name);
  await page.locator(`[data-suspect="${wrong2}"]`).click();
  await page.locator('[data-action="accuse"]').click();
  await page.locator('[data-action="confirm-accuse"]').click();
  await page.waitForSelector('.end.is-loss');
  await overflow('loss');
  assert((await page.locator('.end').innerText()).toLowerCase().includes('cold case'), 'loss ending missing');
  await shot('mobile-loss');

  await page.locator('[data-action="details"]').click();
  const anySuspect = await page.evaluate(() => current.suspects[0].name);
  await page.locator(`[data-suspect="${anySuspect}"]`).click();
  await page.locator('[data-action="accuse"]').click();
  await page.keyboard.press('Escape');
  assert(await page.locator('.modal').count() === 0, 'Escape did not close modal');

  assert(errors.length === 0, `page errors: ${errors.join(' | ')}`);
  console.log('MOBILE PASS 390x844 — office, scene, 4 clues, board, confirmation, win/loss, Escape, no overflow.');
  console.log('killer sample:', killer);
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
