node <<'JS'
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const assert = (ok, msg) => { if (!ok) throw new Error(msg); };
(async () => {
  const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
  const widths = [320, 360, 390, 414, 768, 1024, 1280];
  for (const width of widths) {
    const height = width < 600 ? 844 : 900;
    const page = await browser.newPage({ viewport: { width, height }, deviceScaleFactor: 1 });
    const errors = []; page.on('pageerror', e => errors.push(e.message));
    await page.goto('http://localhost:3002', { waitUntil: 'domcontentloaded' });
    await page.waitForSelector('.office'); await page.waitForTimeout(250);
    let m = await page.evaluate(() => ({ sw: document.documentElement.scrollWidth, iw: innerWidth }));
    assert(m.sw <= m.iw + 1, `${width} office overflow ${m.sw}/${m.iw}`);
    await page.locator('[data-action="head"]').click();
    m = await page.evaluate(() => ({ sw: document.documentElement.scrollWidth, iw: innerWidth }));
    assert(m.sw <= m.iw + 1, `${width} scene overflow ${m.sw}/${m.iw}`);
    const bodyW = (await page.locator('.scene-body').boundingBox()).width;
    assert(bodyW > (width < 400 ? 70 : 100), `${width} scene body too small ${bodyW}`);
    // jump to a fully-evidenced board
    await page.evaluate(() => { current.found = Object.keys(OBJECTS); current.stage = 'board'; current.selected = current.suspects[0].name; render(); });
    await page.waitForSelector('.board');
    m = await page.evaluate(() => ({ sw: document.documentElement.scrollWidth, iw: innerWidth }));
    assert(m.sw <= m.iw + 1, `${width} board overflow ${m.sw}/${m.iw}`);
    const suspect = await page.locator('.suspect-card').first().boundingBox();
    const dock = await page.locator('.board-actions').boundingBox();
    if (width < 600) {
      assert(suspect.width > width - 80, `${width} suspect card narrow: ${Math.round(suspect.width)}`);
      assert(dock.height < 90, `${width} dock tall: ${Math.round(dock.height)}`);
    } else {
      assert(suspect.width < width * 0.4, `${width} suspect card too wide: ${Math.round(suspect.width)}`);
    }
    const accuseW = (await page.locator('[data-action="accuse"]').boundingBox()).width;
    if (width >= 900) assert(accuseW < 260, `${width} accuse button too wide: ${Math.round(accuseW)}`);
    await page.locator('[data-action="accuse"]').click();
    await page.waitForTimeout(650);
    const modal = await page.locator('.modal').boundingBox();
    assert(modal.y >= 0 && modal.y + modal.height <= height + 1, `${width} modal clipped ${JSON.stringify(modal)}`);
    const visibleButtons = await page.locator('.modal button').evaluateAll(els => els.filter(el => { const r = el.getBoundingClientRect(); return r.width > 0 && r.height > 0; }).map(el => [Math.round(el.getBoundingClientRect().width), Math.round(el.getBoundingClientRect().height)]));
    assert(visibleButtons.every(([w,h]) => w >= 36 && h >= 36), `${width} modal tap target small ${JSON.stringify(visibleButtons)}`);
    assert(errors.length === 0, `${width} errors: ${errors.join('; ')}`);
    await page.close();
    console.log(`PASS ${width}x${height}`);
  }
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
