const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const assert = (ok, msg) => { if (!ok) throw new Error(msg); };
(async () => {
  const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });

  // Case-generation invariants across many random cases
  const auditPage = await browser.newPage({ viewport: { width: 390, height: 844 } });
  await auditPage.goto('http://localhost:3002', { waitUntil: 'domcontentloaded' });
  await auditPage.waitForSelector('.office');
  const audit = await auditPage.evaluate(() => {
    const problems = [];
    for (let i = 0; i < 80; i += 1) {
      startCase();
      if (current.suspects.length !== 3) problems.push('suspect count');
      if (new Set(current.suspects.map(s => s.name)).size !== 3) problems.push('duplicate suspect');
      if (!current.suspects.includes(current.killer)) problems.push('killer not a suspect');
      const gunKeys = Object.keys(current.evidence).filter(k => current.evidence[k].gun);
      if (gunKeys.length !== 1) problems.push('gun count ' + gunKeys.length);
      if (!data.weapons.includes(current.weapon)) problems.push('bad weapon');
      for (const key of Object.keys(OBJECTS)) {
        if (!current.evidence[key].title || !current.evidence[key].text) problems.push('empty clue ' + key);
      }
    }
    return [...new Set(problems)];
  });
  assert(audit.length === 0, 'case audit: ' + audit.join(', '));
  console.log('CASE AUDIT PASS — 80 random cases, one smoking gun each, no duplicate suspects.');

  // Full mobile playthrough
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
  const errors = []; page.on('pageerror', e => errors.push(e.message));
  const overflow = async (label) => { const m = await page.evaluate(() => ({ sw: document.documentElement.scrollWidth, iw: innerWidth })); assert(m.sw <= m.iw + 1, `${label}: overflow ${m.sw}/${m.iw}`); };
  const shot = (name, full = true) => page.screenshot({ path: `screenshots/${name}.jpg`, type: 'jpeg', quality: 72, fullPage: full });

  await page.goto('http://localhost:3002', { waitUntil: 'domcontentloaded' });
  await page.waitForSelector('.office'); await page.waitForTimeout(500);
  await overflow('office');
  await shot('mobile-office');
  await page.locator('[data-action="head"]').click();
  await overflow('scene');
  await shot('mobile-scene');
  assert(await page.locator('.hotspot-no').count() === 4, 'hotspot numbers missing');
  for (const key of ['desk', 'window', 'coat', 'body']) {
    await page.locator(`.poi[data-object="${key}"]`).click();
    await page.waitForSelector('.zoom');
    if (key === 'desk') await shot('mobile-zoom');
    await page.locator('[data-action="scene"]').click();
  }
  await page.locator('[data-action="board"]').click();
  await page.waitForSelector('.board');
  await overflow('board');
  assert(await page.locator('.panel-note').isVisible(), 'detective note missing');
  assert(await page.locator('.evidence-card.is-gun').count() === 1, 'smoking gun card missing');
  const killer = await page.evaluate(() => current.killer.name);
  await page.locator(`[data-suspect="${killer}"]`).click();
  assert(await page.locator('.suspect-card.selected').count() === 1, 'selected card state missing');
  await page.evaluate(() => window.scrollTo(0, 0));
  await page.waitForTimeout(250);
  await shot('mobile-board-top', false);
  await page.locator('.suspect-card.selected').scrollIntoViewIfNeeded();
  await page.waitForTimeout(250);
  await shot('mobile-board-suspects', false);
  await page.locator('[data-action="accuse"]').click();
  await page.waitForSelector('.modal');
  await page.waitForTimeout(650);
  const modalBox = await page.locator('.modal').boundingBox();
  assert(modalBox.y >= 0 && modalBox.y + modalBox.height <= 845, 'mobile modal clipped');
  await shot('mobile-accuse', false);
  await page.locator('[data-action="confirm-accuse"]').click();
  await page.waitForSelector('.end.is-win');
  await overflow('win');
  await shot('mobile-win');
  assert((await page.locator('.end').innerText()).toLowerCase().includes('case closed'), 'win copy missing');

  // New case + wrong accusation
  await page.locator('[data-action="new"]').click();
  await page.waitForSelector('.office');
  await page.locator('[data-action="head"]').click();
  for (const key of ['desk', 'window', 'coat', 'body']) {
    await page.locator(`.poi[data-object="${key}"]`).click();
    await page.locator('[data-action="scene"]').click();
  }
  await page.locator('[data-action="board"]').click();
  const wrong = await page.evaluate(() => current.suspects.find(s => s.name !== current.killer.name).name);
  await page.locator(`[data-suspect="${wrong}"]`).click();
  await page.locator('[data-action="accuse"]').click();
  await page.locator('[data-action="confirm-accuse"]').click();
  await page.waitForSelector('.end.is-loss');
  assert((await page.locator('.end').innerText()).toLowerCase().includes('cold case'), 'loss copy missing');
  await overflow('loss');
  await shot('mobile-loss');

  // Accusation without the smoking gun still warns
  await page.locator('[data-action="new"]').click();
  await page.locator('[data-action="head"]').click();
  await page.locator('[data-action="board"]').click();
  const noGun = await page.evaluate(() => current.suspects[0].name);
  await page.locator(`[data-suspect="${noGun}"]`).click();
  await page.locator('[data-action="accuse"]').click();
  await page.waitForSelector('.modal');
  assert((await page.locator('.modal-alert').innerText()).includes('smoking gun'), 'missing no-gun warning');
  await page.keyboard.press('Escape');
  assert(await page.locator('.modal').count() === 0, 'Escape did not dismiss modal');

  assert(errors.length === 0, 'page errors: ' + errors.join(' | '));
  console.log('MOBILE PASS 390x844 — full win, loss, no-gun warning, Escape, no overflow.');

  // Desktop
  const d = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  await d.goto('http://localhost:3002', { waitUntil: 'domcontentloaded' });
  await d.waitForSelector('.office'); await d.waitForTimeout(400);
  const cols = await d.evaluate(() => { const a = document.querySelector('.office-art').getBoundingClientRect(); const c = document.querySelector('.office-copy').getBoundingClientRect(); return c.left > a.right; });
  assert(cols, 'desktop office is not two-column');
  await d.locator('[data-action="head"]').click();
  for (const key of ['desk', 'window', 'coat', 'body']) { await d.locator(`.poi[data-object="${key}"]`).click(); await d.locator('[data-action="scene"]').click(); }
  await d.locator('[data-action="board"]').click();
  const panel = await d.evaluate(() => { const a = document.querySelectorAll('.board-panel'); return { left: a[0].getBoundingClientRect().height, right: a[1].getBoundingClientRect().height, err: [...document.querySelectorAll('.evidence-card.is-gun p')].map(p => getComputedStyle(p).paddingRight) }; });
  assert(Math.abs(panel.left - panel.right) < 2, `desktop board panels unequal: ${panel.left}/${panel.right}`);
  const dk = await d.evaluate(() => current.killer.name);
  await d.locator(`[data-suspect="${dk}"]`).click();
  await d.locator('[data-action="accuse"]').click();
  await d.waitForTimeout(650);
  const db = await d.locator('.modal').boundingBox();
  assert(db.y >= 0 && db.y + db.height <= 901, 'desktop modal clipped');
  await d.locator('[data-action="confirm-accuse"]').click();
  await d.waitForSelector('.end.is-win');
  await d.screenshot({ path: 'screenshots/desktop-win.jpg', type: 'jpeg', quality: 74, fullPage: true });
  console.log('DESKTOP PASS 1280x900 — two-column layouts, equal board panels, modal, win.');
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
